import java.util.*;
public class Main {
    public static void main(String[] a) {
        Scanner s = new Scanner(System.in);
        int n = s.nextInt();
        int p = s.nextInt(), c = 1, b = 1;
        for (int i = 1; i < n; i++) {
            int x = s.nextInt();
            if (x == p) c++;
            else { c = 1; p = x; }
            if (c > b) b = c;
        }
        System.out.println(b);
    }
}
